// Top-down with memo
Map<Integer, Integer> memo = new HashMap<>();
int fib(int n) {
    if (n <= 1) return n;
    if (memo.containsKey(n)) return memo.get(n);
    int res = fib(n-1) + fib(n-2);
    memo.put(n, res);
    return res;
}

